REPLACE INTO `equipment_product` VALUES ('e90b127c-3e2c-4d88-ba51-795a82e04dc7','스마트 단상 계량기','SM-1P-40A','탄소이음','meter','[\"residential\"]','{\"phase\": \"단상 2선\", \"accuracy\": \"클래스 1\", \"wireless\": \"Wi-Fi 802.11b/g/n\", \"dimensions\": \"72×72×60mm\", \"powerInput\": \"AC 90~250V (자가공급)\", \"measurements\": [\"유효전력\", \"전력량\", \"역률\"], \"ratedCurrent\": \"40A (직결형)\", \"certifications\": [\"KC\", \"한국형식승인\"]}','[\"MODBUS RTU\", \"MQTT\"]',95000.00,'가정·소형매장용 스마트 단상 계량기 (최대 40A). Wi-Fi 내장, 월별 요금 자동 계산.',NULL,'easy',12,1,'2026-03-07 12:00:55.670','2026-03-07 12:00:55.670','EP-20260307-0006');
REPLACE INTO `regulatory_sandbox` VALUES ('59d3213c-be4e-4b50-80ad-a51682bf83d4','59cedae9-4998-4844-9994-a21a5efb33c7','AI 기반 건물 수요반응(DR) 자동 참여 서비스 규제 특례','EMS 플랫폼의 AI 엔진이 한전 DR 신호 수신 즉시 HVAC·조명·EV충전기를 자동 제어하여 수요반응에 자동 참여하는 서비스입니다.\n\n현행 수요자원 거래시장 운영규칙은 DR 자원의 수동 확인(운영자 승인) 절차를 요구하여 ms 단위 자동화가 불가합니다.\n실증 대상: 연면적 5,000㎡ 이상 상업 빌딩 10개소\n예상 절감: 피크시간대 15~25% 전력 절감','demand_response','수요자원 거래시장 운영규칙 제18조(수요자원 등록 요건) 中 수동 확인 의무\n전력시장운영규칙 제94조(수요감축지시 이행 방법) — AI 자동화 허용 한정','reviewing','2026-01-23 05:22:56.696','2026-02-17 05:22:56.696',NULL,NULL,NULL,'기술 검증 서류 추가 제출 요청 (2026-04-15 기한). AI 제어 알고리즘 안전성 평가서 필요.',NULL,'박스마트','smart@buildingco.kr','070-9876-5432','2026-03-09 05:22:56.696','2026-03-09 05:22:56.696');
REPLACE INTO `regulatory_sandbox` VALUES ('6079d276-e8f4-439e-820a-aebe38e36308','3751b9cd-c2bd-4803-963f-43b888d11e3e','중소기업 RE100 달성을 위한 소규모 태양광 PPA 중개 플랫폼','연간 전력 소비량 100GWh 미만 중소기업이 개별 협상 없이 플랫폼을 통해 태양광 발전사업자와 장기 전력구매계약(PPA)을 체결할 수 있는 마켓플레이스를 운영합니다.\n\n현행 전기사업법상 전력 중개업은 허가제이며, RE100 PPA는 대기업 위주로만 실질적으로 활용됩니다.\n목표: SME 100개사, 연간 50GWh RE100 달성 지원','re100','전기사업법 제2조(정의) 및 제7조(전기사업 허가) 中 전력 중개 행위\n신에너지 및 재생에너지 개발이용보급 촉진법 시행령 제18조','pending','2026-03-02 05:22:56.696',NULL,NULL,NULL,NULL,NULL,NULL,'이재생','re100@greenpower.co.kr','031-555-7777','2026-03-09 05:22:56.696','2026-03-09 05:22:56.696');
REPLACE INTO `regulatory_sandbox` VALUES ('98d4c79e-ced7-48ee-af95-cc4f9157ab5f','57599fd0-7121-40fc-b697-5f762e5e72ed','IoT 기반 소규모 태양광 P2P 전력 거래 플랫폼 실증 특례','옥상 태양광(3~10kW) 설치 건물 간 잉여 전력을 블록체인 기반 플랫폼으로 직접 거래하는 서비스입니다.\n현행 전기사업법상 전력 소매는 한전 독점이나, 규제 샌드박스 특례를 통해 공동주택 단지 내 P2P 거래를 실증합니다.\n\n적용 기술: ESP32 + PZEM-004T 전력 계측, MQTT 프로토콜, ERC-20 기반 탄소토큰 연동\n실증 규모: 50세대, 총 설치 용량 120kW, 기간 12개월','p2p_energy','전기사업법 제7조(전기사업 허가), 제16조(전기판매사업의 허가)\n전력시장운영규칙 제3조(시장참여자 자격) — 소규모 분산에너지 거래 한정','approved','2025-09-10 05:22:56.696','2025-10-10 05:22:56.696','2025-12-09 05:22:56.696','admin','2026-09-10','실증 구역을 수도권 단일 아파트 단지(500세대 이하)로 제한 승인.\n조건: ① 한국에너지공단 분기별 모니터링 보고 ② 전력 역류 방지 장치 설치 필수 ③ 거래 데이터 산업부 공유.','{\"area\": \"수도권\", \"maxHouseholds\": 500, \"reportingCycle\": \"quarterly\"}','김에너지','energy@example.com','02-1234-5678','2026-03-09 05:22:56.696','2026-03-09 05:22:56.696');
REPLACE INTO `regulatory_sandbox` VALUES ('a5515898-4af9-4484-bb1b-5e0ac75887dc','072ebc57-334b-4337-9e0c-7df5d4b1b25f','K-ETS 배출권(KAU) 블록체인 토큰화 및 소규모 거래 서비스','온실가스 배출권(KAU/KCU)을 ERC-20 토큰으로 표준화하여 기업 간 실시간 장외거래(OTC)를 지원하는 서비스입니다.\n\n현행 K-ETS는 배출권등록부(KRX)를 통한 중앙화 거래만 허용하며, 블록체인 기반 토큰화는 법적 지위가 불명확합니다.\n대상: 배출권 할당 기업 중 자발적 참여 기업 30개사','carbon_market','온실가스 배출권의 할당 및 거래에 관한 법률 제22조(배출권의 거래)\n자본시장법 제4조(증권의 정의) 관련 토큰 증권 해당 여부 불확실성 해소 필요','rejected','2025-07-12 05:22:56.696','2025-08-11 05:22:56.696','2025-09-30 05:22:56.696','admin',NULL,'자본시장법 관련 금융위원회 사전 협의가 선결 요건입니다.\n배출권 토큰화는 증권형 토큰(STO) 규제 프레임워크 완비 후 재신청 권고.\n→ 재신청 시 금융위 혁신금융서비스 지정과 병행 신청 권장.',NULL,'최탄소','carbon@tokenize.io','02-9988-1234','2026-03-09 05:22:56.696','2026-03-09 05:22:56.696');
REPLACE INTO `regulatory_sandbox` VALUES ('be19afbf-6bc3-4656-a64e-1c082dc0787a','5cbddb7c-2f65-44b3-8278-cd31c0199e60','공동주택 IoT EMS 원격 검침 및 에너지 절약 컨설팅 서비스','아파트 세대별 스마트 계량기 데이터를 AI로 분석하여 에너지 절약 목표와 실시간 피드백을 제공하는 구독형 서비스.\n\n현행 전기통신사업법 및 개인정보보호법상 세대별 전력 소비 패턴은 민감정보로 제3자 제공에 제한이 있습니다.\n실증 대상: 수도권 아파트 3개 단지, 1,500세대','ems_new','개인정보보호법 제17조(개인정보의 제공) — EMS 플랫폼에 에너지 데이터 제공 허용\n전기통신사업법 제83조(통신비밀의 보호) 관련 에너지 데이터 예외 적용','approved','2025-02-02 05:22:56.696','2025-03-04 05:22:56.696','2025-04-03 05:22:56.696','admin','2026-04-03','개인정보 보호 조치 강화 조건부 승인:\n① 세대 동의서 100% 징구 ② 데이터 익명화(k-익명성 5 이상) ③ 6개월마다 개인정보 영향평가 실시\n특례 만료 전 연장 신청 필요 (만료 60일 전까지).','{\"kAnonymity\": 5, \"consentRequired\": true, \"impactAssessmentCycle\": \"biannual\"}','정에너지','ems@smartapt.co.kr','032-333-9090','2026-03-09 05:22:56.696','2026-03-09 05:22:56.696');
