-- ============================================================
-- 탄소이음 EMS AIoT — 서버 DB 시드 SQL
-- 로컬 DB 2026-04-14 기준 추출
-- 실행: mysql -u ems -p'PASSWORD' energy < seed_full.sql
-- ============================================================
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;

-- ── 구버전 메뉴 삭제 (새 구성에 없는 코드) ──────────────────
DELETE FROM menu_item WHERE code NOT IN (
  'dashboard_overview','dashboard_realtime','dashboard_viewer','dashboard_digital_twin',
  'monitoring_overview','monitoring_pipeline',
  'analytics_energy','analytics_cost','analytics_carbon','analytics_anomaly',
  'analytics_forecast','analytics_simulator','analytics_templates','analytics_reports',
  'analytics_raw_data','analytics_download','analytics_carbon_trading',
  'analytics_carbon_market_prices','analytics_carbon_roadmap','analytics_benchmark',
  'control_manual','control_schedule','control_optimization','control_dr',
  'management_sites','management_users','management_subscription',
  'control_devices','control_gateways','management_asset',
  'settings_account','settings_notifications','settings_api',
  'settings_system','settings_manual','settings_support',
  'compliance_audit','compliance_emission_factors','compliance_reports',
  'alerts_overview','alerts_rules',
  'admin_tenants','admin_menu','admin_traffic','admin_support',
  'admin_partners','resource_Management','admin_sandbox',
  'admin_security','admin_ransomware','super_admin_retention','super_admin_erp'
);

DELETE FROM menu_group WHERE code NOT IN (
  'dashboard','monitoring','analytics','control','management',
  'settings','compliance','alerts','admin'
);

-- ─────────────────────────────────────────────────────────────────────
-- 가격 근거 (2026-04 ROI 기반 재산정)
--
-- 핵심 원칙: 절감액 기반 가격 (ROI 5~15%)
--   전기료 1,000만원/월 고객 → 절감 8% = 80만원 절감 → 월 40~120만원 SaaS 지불 가능
--
-- 운영비 (NCP 150K + 도메인 18K + AI API 50K + SMS 30K = 268K/월 고정비)
-- trial  : 무료 체험 14일 (리드 확보 도구)
-- basic  : 99K/월 (스타터) — 소규모 사업장, 절감 50~100만원 수준 대상
-- pro    : 299K/월 (비즈니스) — 중소기업, 절감 300~500만원 수준 대상
-- enterprise: 790K~/월 — 대기업/공공, 절감 1,000만원+ 수준 대상
--
-- 구축비(setupFee): 초기 세팅·교육·Gateway 연동 비용 (현장 방문 없는 경우 기준)
-- basic  구축비: 0원 (셀프 온보딩)
-- pro    구축비: 500,000원
-- enterprise 구축비: 1,500,000원 (협의)
-- ─────────────────────────────────────────────────────────────────────

SET FOREIGN_KEY_CHECKS=1;
SELECT CONCAT('feature: ', COUNT(*)) AS result FROM feature
UNION ALL SELECT CONCAT('plan: ', COUNT(*)) FROM plan
UNION ALL SELECT CONCAT('emission_factor: ', COUNT(*)) FROM emission_factor
UNION ALL SELECT CONCAT('carbon_market_price: ', COUNT(*)) FROM carbon_market_price
UNION ALL SELECT CONCAT('menu_group: ', COUNT(*)) FROM menu_group
UNION ALL SELECT CONCAT('menu_item: ', COUNT(*)) FROM menu_item
UNION ALL SELECT CONCAT('equipment_product: ', COUNT(*)) FROM equipment_product;
